#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

OWNER="mighty-muffin"
REPO="stoopid"
REPO_SLUG="$OWNER/$REPO"
WORKFLOW="release.yml"

cd "$(git rev-parse --show-toplevel)"
export GH_REPO="$REPO_SLUG"   # gh secret/variable/run target this repo

# installed SLUG → success if the GitHub App SLUG is installed on the org.
installed() {
  gh api "orgs/$OWNER/installations" --jq '.installations[].app_slug' 2>/dev/null | grep -qx "$1"
}

banner "stoopid: one-time release pipeline setup"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "PyPI: pending trusted publisher"
say "Lets release.yml publish 'stoopid' to PyPI over OIDC: no API token."
open_url "https://pypi.org/manage/account/publishing/"
step "Log in (2FA) if asked. Under 'Add a new pending publisher', pick the GitHub tab."
step "PyPI Project Name:  ${BOLD}$REPO${RESET}"
step "Owner:              ${BOLD}$OWNER${RESET}"
step "Repository name:    ${BOLD}$REPO${RESET}"
step "Workflow name:      ${BOLD}$WORKFLOW${RESET}"
step "Environment name:   ${BOLD}pypi${RESET}"
step "Click 'Add'. It should appear under 'Pending publishers'."
note "PyPI has no public API for this, so the wizard can't check it for you."
pause "Done on PyPI? Press Enter"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "TestPyPI: pending trusted publisher"
say "Same again on TestPyPI (a separate site with its own account)."
open_url "https://test.pypi.org/manage/account/publishing/"
note "No TestPyPI account? Register at https://test.pypi.org/account/register/ first."
step "GitHub tab → PyPI Project Name: ${BOLD}$REPO${RESET}   Owner: ${BOLD}$OWNER${RESET}"
step "Repository name: ${BOLD}$REPO${RESET}   Workflow name: ${BOLD}$WORKFLOW${RESET}"
step "Environment name: ${BOLD}testpypi${RESET}   (not 'pypi')"
step "Click 'Add'."
pause "Done on TestPyPI? Press Enter"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "GitHub App for release-please: create it"
say "release-please needs a token whose PRs trigger CI; the default GITHUB_TOKEN's don't."
say "The page opens pre-filled (name, no webhook, permissions)."
open_url "https://github.com/organizations/$OWNER/settings/apps/new?name=$OWNER-release-please&url=https://github.com/$REPO_SLUG&public=false&webhook_active=false&contents=write&pull_requests=write&issues=write"
step "Check the form, fix anything not pre-filled:"
note "    GitHub App name: $OWNER-release-please (must be globally unique; tweak if taken)"
note "    Webhook → Active: ${BOLD}unchecked${RESET}"
note "    Repository permissions: Contents, Pull requests, Issues → ${BOLD}Read and write${RESET}"
note "    Where can this app be installed: ${BOLD}Only on this account${RESET}"
step "Click 'Create GitHub App'."
step "On the app's General page, copy the ${BOLD}App ID${RESET} (a number, not the Client ID)."
ask RELEASE_APP_ID "Paste the App ID:"
until [[ "$RELEASE_APP_ID" =~ ^[0-9]+$ ]]; do
  warn "that isn't a number"
  ask RELEASE_APP_ID "Paste the App ID:"
done
set_var RELEASE_APP_ID "$RELEASE_APP_ID"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "GitHub App: private key + install on $REPO"
step "Same page, scroll to 'Private keys' → 'Generate a private key'. A .pem downloads."
note "On WSL your Windows Downloads folder is under /mnt/c/Users/<you>/Downloads/"
ask PEM_PATH "Path to the downloaded .pem file:"
until [[ -f "$PEM_PATH" ]] && grep -q 'PRIVATE KEY' "$PEM_PATH"; do
  warn "not a readable private key file: $PEM_PATH"
  ask PEM_PATH "Path to the downloaded .pem file:"
done
set_secret RELEASE_APP_PRIVATE_KEY "$(cat "$PEM_PATH")"
if confirm "Delete $PEM_PATH now that it's stored as a GitHub secret?"; then
  rm -f "$PEM_PATH" && note "deleted"
fi
step "Left sidebar → 'Install App' → Install on ${BOLD}$OWNER${RESET}."
step "Choose 'Only select repositories' → ${BOLD}$REPO${RESET} → Install."
pause "Installed? Press Enter"
APP_SLUG=$(gh api "apps/$OWNER-release-please" --jq .slug 2>/dev/null || true)
if [[ -n "$APP_SLUG" ]] && installed "$APP_SLUG"; then
  printf '  %s✓ verified%s %s is installed on %s\n' "$GREEN" "$RESET" "$APP_SLUG" "$OWNER"
else
  warn "couldn't confirm the install (fine if you changed the app name); check the org's GitHub Apps page"
fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Renovate: install the app"
if installed renovate; then
  printf '  %s✓ Renovate is already installed on %s%s\n' "$GREEN" "$OWNER" "$RESET"
  say "Make sure its repository access includes $REPO:"
fi
open_url "https://github.com/apps/renovate"
step "Click 'Install' (or 'Configure') → choose ${BOLD}$OWNER${RESET}."
step "Pick 'Only select repositories' → add ${BOLD}$REPO${RESET} → Install / Save."
note "renovate.json is already committed, so Renovate skips its onboarding PR."
pause "Done? Press Enter"
if installed renovate; then
  printf '  %s✓ verified%s Renovate is installed on %s\n' "$GREEN" "$RESET" "$OWNER"
else
  SKIPPED+=("Renovate install on $REPO_SLUG (not detected)")
  warn "Renovate not detected on $OWNER yet"
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Kick off the release pipeline"
say "The first Release run failed because the GitHub App wasn't set up yet."
say "Re-running it opens the first release PR (0.1.0) and publishes a dev build to TestPyPI."
RUN_ID=$(gh run list --workflow "$WORKFLOW" --branch main --limit 1 --json databaseId --jq '.[0].databaseId' 2>/dev/null || true)
if [[ -z "$RUN_ID" ]]; then
  warn "no Release run found yet; push to main to trigger one"
elif confirm "Re-run Release run $RUN_ID now?"; then
  gh run rerun "$RUN_ID" >/dev/null && printf '  %s✓ re-run started%s\n' "$GREEN" "$RESET"
  open_url "https://github.com/$REPO_SLUG/actions/runs/$RUN_ID"
  note "Then merge the 'chore(main): release 0.1.0' PR to publish 0.1.0 to PyPI."
fi
pause

finish
}

run_wizard "$@"; exit
